import os
import time
import logging
import requests
from inspect import getcallargs
from datetime import timedelta
from dateutil import parser as date_parser
from functools import wraps
from taf.sw.scout import scout
from taf.sw.scout.exceptions import GetRequestException, PostRequestException, ConnectionException, TimeoutException
from taf.sw.scout.config import ProductionConfig


def connect_to_scout(function):
    @wraps(function)
    def wrapper(self, *args, **kwargs):
        passed_args = getcallargs(function, self, *args, **kwargs)
        scout_bts_name = passed_args.get('test_line_name', passed_args.get('scout_bts_name', None))
        try:
            self._connect_to_scout(scout_bts_name)
            results = function(self, *args, **kwargs)
        finally:
            self.scout.teardown_scout_api(alias=scout_bts_name)
        return results

    return wrapper


class GenericScout(object):
    def __init__(self, test_line_name=None, api_key=None, bts_type='GNB'):
        # api_key = 'a010cd9f185846c6ac6adb91dd70d526' --> old value of API key
        self.test_line_name = test_line_name
        self.api_key = api_key
        self.bts_type = bts_type
        self.scout = scout()

    @staticmethod
    def get_url_link_for_testline(testline_name):
        """
        Get URL link for testline.

        :param testline_name: testline name
        :return: str - URL link for testline
        """
        return "{}/testlines/{}/preview/".format(ProductionConfig.BASE_URL, testline_name)

    @staticmethod
    def is_bts_defined_in_scout(scout_bts_name, timeout=60):
        """
        Check if a BTS is defined in Scout.
        :param scout_bts_name: Name of the scout BTS.
        :param timeout: Timeout for the request in seconds.
        :return: bool - True if the BTS is defined in Scout, False otherwise
        """
        end_point_url = GenericScout._get_endpoint_url_for_getting_testline_details()
        params = {
            'filter[name]': scout_bts_name,
        }
        resp_json = GenericScout.get_response(url=end_point_url, params=params, timeout=timeout)
        return bool(resp_json.get('data'))

    @staticmethod
    def get_url_link_for_scf_analysis(testline_name, scf_id=None):
        """
        Get URL link for SCF analysis of a testline.
        :param testline_name: testline name
        :param scf_id: SCF ID (optional)
        :return: str - URL link for SCF analysis of a testline
        """
        link = "{}/testlines/{}/scf-analysis-list/".format(ProductionConfig.BASE_URL, testline_name)
        if scf_id:
            link += "?fSID={}".format(scf_id)
        return link

    @connect_to_scout
    def get_bts_monitor_status(self, scout_bts_name=None) -> dict[str, str]:
        """
        Get the testline status for a given scout BTS name.
        :param scout_bts_name: Name of the scout BTS.
        :return: The testline status. eg:
            {'admin_cli_status_display': 'running',
             'admin_pm_status_display': 'running',
             'admin_subscriptions_status_display': 'not running',
             'admin_websocket_status_display': 'running',
             'container_status_display': 'running',
             'pm_status_display': 'blocked',
             'ssh_status_display': 'blocked',
             'websocket_status_display': 'connected'}

        """
        tl_status = self.scout.get_testline_monitor_status(alias=scout_bts_name)
        return tl_status

    @connect_to_scout
    def get_bts_status(self, scout_bts_name=None) -> dict[str, str]:
        """
        Get the BTS status for a given scout BTS name.
        :param scout_bts_name: Name of the scout BTS.
        :return: The BTS status. eg: onAir
        """
        return self.scout.get_scout_testline_status(alias=scout_bts_name)

    @staticmethod
    def get_testline_owner_info_from_scout(testline_name, timeout=60):
        """
        Get testline owner info from scout.

        :param testline_name: testline name
        :param timeout: Timeout for the request in seconds.
        :return: dict - testline details
        """
        owner_details = {}
        end_point_url = GenericScout._get_endpoint_url_for_getting_testline_details()
        params = {
            'exclude_fields[testline]': 'infomodel',
            'filter[name]': testline_name,
            'include': 'user,team'
        }
        results = GenericScout.get_response(url=end_point_url, params=params, timeout=timeout)
        if results.get('data') and results.get('included'):
            included = results['included']
            for attribute in included:
                if attribute['type'] == 'team':
                    owner_details['team_email'] = attribute['attributes']['email']
                    owner_details['team_name'] = attribute['attributes']['name']
                if attribute['type'] == 'user':
                    owner_details['owner_email'] = attribute['attributes']['email']
                    owner_details['owner_name'] = attribute['attributes']['display_name']
            if owner_details:
                owner_details['link'] = GenericScout.get_url_link_for_testline(testline_name)

        return owner_details

    @staticmethod
    def get_bts_details(testline_name, include_user=False, include_team=False, include_monitor=False,
                        exclude_infomodel=False, timeout=60):
        """
        Get testline details from scout.

        :param testline_name: testline name
        :param include_user: if True, include user details in the response
        :param include_team: if True, include team details in the response
        :param include_monitor: if True, include monitor details in the response
        :param exclude_infomodel: if True, exclude infomodel from the response
        :param timeout: Timeout for the request in seconds.
        :return: dict - testline details
        """
        end_point_url = GenericScout._get_endpoint_url_for_getting_testline_details()
        params = {
            'filter[name]': testline_name,
        }
        if exclude_infomodel:
            params['exclude_fields[testline]'] = 'infomodel'

        include = []
        if include_user:
            include.append('user')
        if include_team:
            include.append('team')
        if include_monitor:
            include.append('monitor')
        if include:
            params['include'] = ','.join(include)

        resp_json = GenericScout.get_response(url=end_point_url, params=params, timeout=timeout)
        data = resp_json['data'][0] if resp_json['data'] else {}
        return {'data': data, 'included': resp_json.get('included', [])}

    @staticmethod
    def get_bts_id(testline_name):
        """
        Get bts ID from scout. Just ID without MRBTS- prefiix
        :param testline_name: testline name
        :return int: BTS ID
        """
        bts_details = GenericScout.get_bts_details(testline_name)
        bts_id = bts_details['data']['attributes']['infomodel'].get('bts_id')
        return bts_id

    @connect_to_scout
    def get_scf_id(self, scout_bts_name: str, use_scout_internal_id: bool = True, max_attempts: int = 10,
                   interval_between_attempts: int = 10, request_scf_timeout: int = 120,
                   admin_connect_timeout: int = 120) -> str:
        """
        Get the SCF ID for a given scout BTS name.

        :param scout_bts_name: Name of the scout BTS.
        :param use_scout_internal_id: Whether to use the scout internal ID, defaults to True.
        :param max_attempts: Maximum number of attempts to get the SCF ID, defaults to 10.
        :param interval_between_attempts: Interval between attempts in seconds, defaults to 5.
        :param request_scf_timeout: Timeout for the SCF request in seconds, defaults to 120.
        :param admin_connect_timeout: Timeout for the admin connection in seconds, defaults to 120.
        :return: The SCF ID.
        """

        for attempt in range(1, max_attempts + 1):
            interval = interval_between_attempts
            last_exception = None
            try:
                logging.debug(f"Getting SCF ID - attempt number {attempt}")
                scf_id = self.scout.request_scf(use_scout_internal_id=use_scout_internal_id,
                                                timeout=request_scf_timeout,
                                                admin_connect_timeout=admin_connect_timeout,
                                                alias=scout_bts_name)
                return scf_id
            except (ConnectionException, TimeoutException) as e:
                if 'Admin infomodel is not running' in repr(e):
                    interval = 90
                    last_exception = e
            except (GetRequestException, PostRequestException) as e:
                if 'admin_cli_status is not running' in repr(e):
                    interval = 90
                last_exception = e
            finally:
                if last_exception:
                    if attempt == max_attempts:
                        raise last_exception
                    logging.warning(f"Cannot get SCF ID due to: {repr(last_exception)}")
                    logging.debug(f"Waiting {interval} seconds and try again")
                    time.sleep(interval)

    @connect_to_scout
    def generate_kpi_report_on_the_scout(self, report_name, kpi_template_id, start_time, end_time, scout_bts_name=None):
        """
        Open interface for collecting KPI results from Scout.
        Example:
        generate_kpi_report_on_the_scout('Test_kpi_report','awesome_template_id','2020-12-01T12:23:24.426000',
                                         '2020-12-02T10:23:24.426000')
        :param report_name: Name for generated KPI Report.
                            Current date and time will be added as suffix to avoid KPI Report names duplications
        :param kpi_template_id: id of the KPI Template defined in scout eg: 102
        :param start_time: start time from which PM counters will be used, eg: 2020-12-01T12:23:24.426000Z
        :param end_time: end time from which PM counters will be used, eg: 2020-12-02T10:23:24.426000Z
        :param scout_bts_name: Name of the scout BTS - if not passed then self.test_line_name will be used.
        :return: KPI report as a dict
        """
        report_data = []
        try:
            kpi_report = self.scout.generate_kpi_report(report_name, kpi_template_id,
                                                        start_time, end_time, alias=scout_bts_name)[0]
            report_data = kpi_report['report']
            logging.info("Generated Scout report - Name: {}, ID: {}".format(kpi_report['name'], kpi_report['id']))
            logging.debug("Generated report {}".format(kpi_report))
        except Exception as e:
            logging.warning("Cannot generate SCOUT report. {}".format(repr(e)))

        return report_data

    @connect_to_scout
    def wait_for_kpi_data_available_in_scout(self, start_time, attempt=20, interval_checking=30, scout_bts_name=None):
        logging.debug("Waiting for KPI from period start at {}".format(start_time))
        start_time = date_parser.parse("{}Z".format(start_time))
        before_time = int(time.time())
        while attempt:
            kpi_update_time = self.scout.get_last_kpi_update_time(alias=scout_bts_name)
            kpi_update_time = date_parser.parse(kpi_update_time)
            logging.debug("Last KPI update time from SCOUT {}".format(kpi_update_time))
            if start_time <= kpi_update_time:
                logging.info("Scout KPI data are already available for {}".format(start_time))
                break
            attempt -= 1

            logging.debug("Scout PM stats data are not available for {}".format(start_time))
            logging.debug("Waiting {} seconds for next check".format(interval_checking))
            time.sleep(interval_checking)

        logging.debug("Total waiting time: {}".format(timedelta(seconds=int(time.time()) - before_time)))

    def _connect_to_scout(self, scout_bts_name=None):
        scout_bts_name = scout_bts_name or self.test_line_name
        alias = scout_bts_name or 'default'
        self.api_key = self.api_key or self._get_scout_api_key_from_env()
        self.scout.setup_scout(scout_testline_name=scout_bts_name, api_key=self.api_key, alias=alias)

    @staticmethod
    def _get_scout_api_key_from_env():
        api_key = os.environ.get('SCOUT_API_KEY', None)
        return api_key

    @staticmethod
    def _get_endpoint_url_for_getting_testline_details():
        end_point_url = "{}/api/{}/testlines/".format(ProductionConfig.BASE_URL, ProductionConfig.API_VERSION)
        return end_point_url

    @staticmethod
    def get_response(url, params, timeout=60):
        resp = requests.request(url=url, params=params, method='GET', timeout=timeout)
        if resp.status_code in range(200, 300):
            return resp.json()
        else:
            raise GetRequestException('Status code: "{}"; MSG: "{}"'.format(resp.status_code, resp.text),
                                      {'status_code': resp.status_code})
